// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

class LmdbNativeSelectorEdgeCaseTest {

	@Test
	void indexedCountDominanceRemainsTransitiveRegardlessOfRegistryOrder() {
		// These are real declarations from NativeGroupIteration.offerStrategies: indexedCount dominates
		// prefixRunGroups, which in turn dominates orderedSinglePatternGroups. IndexedCount does not repeat
		// the latter edge. Structural dominance is independent of each candidate's estimated price.
		LmdbNativeCandidate<String> indexedCount = candidate(LmdbNativeAttemptMetrics.PATH_INDEXED_COUNT, 1_000_000D)
				.dominating(Set.of(LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS));
		LmdbNativeCandidate<String> prefixRuns = candidate(LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS, 500_000D)
				.dominating(Set.of(LmdbNativeAttemptMetrics.PATH_ORDERED_SINGLE_PATTERN_GROUPS));
		LmdbNativeCandidate<String> orderedGroups = candidate(
				LmdbNativeAttemptMetrics.PATH_ORDERED_SINGLE_PATTERN_GROUPS, 0D);
		List<LmdbNativeCandidate<String>> declarations = List.of(indexedCount, prefixRuns, orderedGroups);
		for (int rotation = 0; rotation < declarations.size(); rotation++) {
			List<LmdbNativeCandidate<String>> candidates = new ArrayList<>(declarations);
			Collections.rotate(candidates, rotation);
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(candidates,
					LmdbNativeStaticPrior.DEFAULT, -1D, 4);
			assertThat(candidates.get(ranking.winner()).id()).as("registry rotation %s", rotation)
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_INDEXED_COUNT);
			assertThat(ranking.eliminatedBy()[candidates.indexOf(orderedGroups)])
					.as("the admitted prefix-run strategy still establishes its structural edge")
					.startsWith("Structurally dominated by ");
		}
	}

	private static LmdbNativeCandidate<String> candidate(String id, double scannedRows) {
		return LmdbNativeCandidate.of(id, LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, scannedRows), 1D), () -> id);
	}
}
